  white-space: pre-wrap;
  line-height: 1.5;
}
.${messageClass}[data-role="user"] {
  background: rgba(0, 0, 0, 0.05);
  border-radius: 0.5rem;
  padding: 0.5rem 0.75rem;
}
.${roleClass} {
  display: block;
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.6;
}
.${composerClass} {
  display: flex;
  gap: 0.5rem;
}
.${composerClass} textarea {
  flex: 1;
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
`);

type MessageState = {
  message: Message;
  mark: { start: number; end: number } | null;
};

class MessageView implements View<MessageState> {
  container: HTMLElement;
  private b: Binder<MessageState>;

  constructor(
    container: HTMLElement,
    _dispatch: (msg: never) => void,
    initial: MessageState,
  ) {
    const roleRef = ref("role");
    const preRef = ref("pre");
    const markRef = ref("mark");
    const postRef = ref("post");
    container.className = messageClass;
    container.innerHTML = sanitize`
      <span class="${roleClass}" data-ref="${roleRef}"></span>
      <span class="${textClass}"><span data-ref="${preRef}"></span><mark class="${markClass}" data-ref="${markRef}"></mark><span data-ref="${postRef}"></span></span>
    `;
    this.container = container;
    this.b = new Binder(container, initial);
    this.b.bindText(roleRef, (s) => s.message.role);
    this.b.bindText(preRef, (s) =>
      s.mark ? s.message.text.slice(0, s.mark.start) : s.message.text,
    );
    this.b.bindText(markRef, (s) =>
      s.mark ? s.message.text.slice(s.mark.start, s.mark.end) : "",
    );
    this.b.bindText(postRef, (s) =>
      s.mark ? s.message.text.slice(s.mark.end) : "",
    );
    this.b.bindContainerAttr("data-role", (s) => s.message.role);
  }

  sync(state: MessageState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class AppView implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const transcriptRef: Ref = ref("transcript");
    const inputRef: Ref = ref("input");
    const sendRef: Ref = ref("send");
    const toggleRef: Ref = ref("toggle");
    const composerRef: Ref = ref("composer");
    const learningRef: Ref = ref("learning");

    container.className = appClass;
    container.innerHTML = sanitize`
      <button type="button" class="${toggleClass}" data-ref="${toggleRef}"></button>
      <div class="${paneClass}">
        <ul class="${transcriptClass}" data-ref="${transcriptRef}"></ul>
        <div class="${composerClass}" data-ref="${composerRef}">
          <textarea data-ref="${inputRef}" rows="2" placeholder="Ask something…"></textarea>
          <button type="button" data-ref="${sendRef}">Send</button>
        </div>
      </div>
      <div data-ref="${learningRef}"></div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    const input = this.b.ref<HTMLTextAreaElement>(inputRef);
    input.addEventListener("input", () => {
      dispatch({ type: "DRAFT_CHANGED", draft: input.value });
    });
    input.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        dispatch({ type: "SUBMIT" });
      }
    });
    this.b
      .ref(sendRef)
      .addEventListener("click", () => dispatch({ type: "SUBMIT" }));
    this.b
      .ref(toggleRef)
      .addEventListener("click", () => dispatch({ type: "MODE_TOGGLED" }));

    // Capture on mouseup/keyup rather than `selectionchange`: the browser
    // collapses the selection as soon as the user clicks the learning pane,
    // which is exactly when we need the anchor to survive.
    const transcript = this.b.ref(transcriptRef);
    const capture = () => {
      const anchor = readAnchor(transcript);
      if (anchor !== undefined) dispatch({ type: "SELECTION_CHANGED", anchor });
    };
    transcript.addEventListener("mouseup", capture);
    transcript.addEventListener("keyup", capture);

    // The transcript is append-only and never reorders, so the position of a
    // message is a stable identity.
    this.b.bindList(transcriptRef, "li", (s) =>
      s.messages.map((message, i) =>
        showKeyed(
          String(i),
          MessageView,
          { message, mark: clipToMessage(s.anchor, i, message.text.length) },
          {},
          noop,
        ),
      ),
    );
    this.b.bindContainerAttr("data-mode", (s) => s.mode);
    this.b.bindText(toggleRef, (s) =>
      s.mode === "task" ? "Switch to learning mode" : "Back to task mode",
    );
    this.b.bindVisible(composerRef, (s) => s.mode === "task");
    this.b.bindSlot(learningRef, (s) => {
      if (s.mode !== "learning") return undefined;
      const learningState: LearningState = {
        selection: s.anchor ? anchorText(s.anchor, s.messages) : null,
        query: s.query,
        pending: s.pending,
      };
      return show(LearningPane, learningState, {}, (msg: LearningMsg) => ({
        type: "LEARNING_MSG" as const,
        msg,
      }));
    });
    this.b.bindValue(inputRef, (s) => s.draft);
    this.b.bindDisabled(inputRef, (s) => s.inFlight);
    this.b.bindDisabled(sendRef, (s) => s.inFlight || s.draft.trim() === "");
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

/** Reads the live browser selection as an Anchor. Returns `undefined` when the
 * selection has nothing to do with the transcript, which must not clobber a
 * previously captured anchor. */
function readAnchor(transcript: HTMLElement): Anchor | null | undefined {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return undefined;
  const range = selection.getRangeAt(0);
  const start = resolvePoint(
    transcript,
    range.startContainer,
    range.startOffset,
  );
  const end = resolvePoint(transcript, range.endContainer, range.endOffset);
  if (!start || !end) return undefined;
  if (start.msg === end.msg && start.offset === end.offset) return null;
  return { start, end };
}

function resolvePoint(
  transcript: HTMLElement,
  node: Node,
  offset: number,
): Point | null {
  const el =
    node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
  const textEl = el?.closest(`.${textClass}`);
  if (!textEl || !transcript.contains(textEl)) return null;
  const li = textEl.closest("li");
  if (!li) return null;
  const msg = Array.prototype.indexOf.call(transcript.children, li);
  if (msg < 0) return null;

  // The message text is split across pre/mark/post spans, so a node-local
  // offset is not a message offset; measure the text preceding the point.
  const prefix = document.createRange();
  prefix.setStart(textEl, 0);
  prefix.setEnd(node, offset);
  return { msg, offset: prefix.toString().length };
}

import { Binder, cls, mountStyle, ref, sanitize, type View } from "./vamp.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

export type State = {
  /** The text the user highlighted, or null when nothing is selected. */
  selection: string | null;
  query: string;
  pending: Action | null;
};

export type Msg =
  | { type: "ACTION"; action: Action }
  | { type: "QUERY_CHANGED"; query: string };

const paneClass = cls("learning-pane");
const emptyClass = cls("learning-empty");
const quoteClass = cls("learning-quote");
const actionsClass = cls("learning-actions");
const pendingClass = cls("learning-pending");

mountStyle(`
.${paneClass} {
  position: sticky;
  top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${emptyClass} {
  opacity: 0.5;
  font-style: italic;
}
.${quoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  padding-left: 0.75rem;
  max-height: 12rem;
  overflow-y: auto;
  font-size: 0.9rem;
}
.${actionsClass} {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
  text-align: left;
  padding: 0.5rem 0.75rem;
}
.${actionsClass} textarea {
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
.${pendingClass} {
  font-size: 0.85rem;
  opacity: 0.6;
}
`);

export class LearningPane implements View<State, Msg> {
  container: HTMLElement;
  private b: Binder<State>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
  ) {
    const emptyRef = ref("empty");
    const bodyRef = ref("body");
    const quoteRef = ref("quote");
    const explainRef = ref("explain");
    const quizRef = ref("quiz");
    const queryRef = ref("query");
    const pendingRef = ref("pending");

    container.className = paneClass;
    container.innerHTML = sanitize`
      <p class="${emptyClass}" data-ref="${emptyRef}">Select some text to get started.</p>
      <div class="${actionsClass}" data-ref="${bodyRef}">
        <blockquote class="${quoteClass}" data-ref="${quoteRef}"></blockquote>
        <button type="button" data-ref="${explainRef}">I don't understand this.</button>
        <button type="button" data-ref="${quizRef}">Quiz me on this.</button>
        <textarea data-ref="${queryRef}" rows="2" placeholder="Ask your own question…"></textarea>
        <span class="${pendingClass}" data-ref="${pendingRef}"></span>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );

    const query = this.b.ref<HTMLTextAreaElement>(queryRef);
    query.addEventListener("input", () => {
      dispatch({ type: "QUERY_CHANGED", query: query.value });
    });
    query.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      const text = query.value.trim();
      if (text === "") return;
      dispatch({ type: "ACTION", action: { type: "query", text } });
    });

    this.b.bindVisible(emptyRef, (s) => s.selection === null);
    this.b.bindVisible(bodyRef, (s) => s.selection !== null);
    this.b.bindText(quoteRef, (s) => s.selection ?? "");
    this.b.bindValue(queryRef, (s) => s.query);
    this.b.bindText(pendingRef, (s) =>
      s.pending === null ? "" : `${describe(s.pending)} — not wired up yet.`,
    );
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

function describe(action: Action): string {
  switch (action.type) {
    case "explain":
      return "Explain this";
    case "quiz":
      return "Quiz me";
    case "query":
      return action.text;
  }
}

import { Conversation } from "../conversation.ts";
import { selectedSample } from "../samples/index.ts";
import { AppView, type Msg, type State } from "../view.ts";

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the plain task-mode transcript. The review affordances get
 * layered on top of this one. */
export function mount(container: HTMLElement): void {
  const conversation = new Conversation(connect(), {
    initialTurns: selectedSample()?.turns,
  });
  const state: State = {
    messages: conversation.messages,
    inFlight: false,
    draft: "",
    mode: "task",
    anchor: null,
    query: "",
    pending: null,
  };

  function update(state: State, msg: Msg): void {
    switch (msg.type) {
      case "DRAFT_CHANGED":
        state.draft = msg.draft;
        break;
      case "SUBMIT": {
        const text = state.draft.trim();
        if (text === "" || conversation.inFlight) break;
        state.draft = "";
        conversation.send(text).then(undefined, (e: unknown) => {
          console.error(e);
        });
        break;
      }
      case "MODE_TOGGLED":
        state.mode = state.mode === "task" ? "learning" : "task";
        break;
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        state.pending = null;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION":
            state.pending = msg.msg.action;
            break;
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
    }
    state.messages = conversation.messages;
    state.inFlight = conversation.inFlight;
  }

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    dispatching = false;
  }

  const view = new AppView(container, dispatch, state);

  conversation.onChange = () => {
    state.messages = conversation.messages;
    state.inFlight = conversation.inFlight;
    view.sync(state);
  };
}

import { type Anchor, anchorText } from "./selection.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript and point at a passage they picked out.",
  "Answer about that passage specifically, in plain language, and assume the",
  "user has not followed the reasoning that produced it. Be concise, and do",
  "not restate the whole transcript back to them.",
].join(" ");

/** The single synthetic user turn seeding a learning thread. `seed` is the
 * parent's own seed and is emitted verbatim - wrapping or re-labelling it
 * would nest the framing one layer deeper at every level. */
export function seedTurn(
  seed: string | undefined,
  messages: ReadonlyArray<{ role: "user" | "assistant"; text: string }>,
  anchor: Anchor,
  action: Action,
): string {
  const visible = messages.slice(0, anchor.end.msg + 1);
  const sections = [];
  if (seed) sections.push(seed);
  sections.push(transcript(visible));
  sections.push(
    `The user then selected: "${anchorText(anchor, visible)}"\n${question(action)}`,
  );
  return sections.join("\n\n");
}

function transcript(
  messages: ReadonlyArray<{ role: "user" | "assistant"; text: string }>,
): string {
  return messages
    .map((m) => `${m.role === "user" ? "User" : "Assistant"}: ${m.text}`)
    .join("\n\n");
}

function question(action: Action): string {
  switch (action.type) {
    case "explain":
      return "They said they don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "They asked to be quizzed on this. Ask one question that checks whether they understand it, and wait for their answer.";
    case "query":
      return `They asked: ${action.text}`;
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";
import { expect, type Page, test } from "@playwright/test";

function events(chunks: string[]): Anthropic.RawMessageStreamEvent[] {
  return [
    {
      type: "content_block_start",
      index: 0,
      content_block: { type: "text", text: "", citations: null },
    },
    ...chunks.map(
      (text): Anthropic.RawMessageStreamEvent => ({
        type: "content_block_delta",
        index: 0,
        delta: { type: "text_delta", text },
      }),
    ),
    { type: "content_block_stop", index: 0 },
    { type: "message_stop" } as Anthropic.RawMessageStreamEvent,
  ];
}

/** Stand in for the backend: replay `chunks` one delta at a time, and expose a
 * promise that resolves once the browser has sent its `start` frame. */
async function fakeBackend(page: Page, chunks: string[]) {
  let release!: () => void;
  const gate = new Promise<void>((resolve) => {
    release = resolve;
  });
  const started: string[] = [];

  await page.routeWebSocket("**/api/socket", (ws) => {
    ws.onMessage(async (raw) => {
      const message = JSON.parse(String(raw)) as ClientMessage;
      started.push(JSON.stringify(message.params.messages));
      await gate;
      const send = (frame: ServerFrame) => ws.send(JSON.stringify(frame));
      for (const event of events(chunks)) {
        send({ type: "event", requestId: message.requestId, event });
      }
      send({ type: "done", requestId: message.requestId });
    });
  });

  return { release, started };
}

test("streams a response into the transcript", async ({ page }) => {
  const backend = await fakeBackend(page, ["Hello", ", world"]);
  await page.goto("/");

  await page.getByRole("textbox").fill("hi");
  await page.getByRole("button", { name: "Send" }).click();

  await expect(page.locator('[data-role="user"]')).toHaveText(/hi/);
  backend.release();

  await expect(page.locator('[data-role="assistant"]')).toHaveText(
    /Hello, world/,
  );
  await expect(page.locator("li")).toHaveCount(2);
});

test("the composer is disabled while a turn is in flight", async ({ page }) => {
  const backend = await fakeBackend(page, ["ok"]);
  await page.goto("/");

  const input = page.getByRole("textbox");
  await input.fill("hi");
  await page.getByRole("button", { name: "Send" }).click();

  await expect(input).toBeDisabled();
  backend.release();
  await expect(input).toBeEnabled();
  await expect(input).toHaveValue("");
});

test("a second turn sends the full conversation", async ({ page }) => {
  const backend = await fakeBackend(page, ["ok"]);
  backend.release();
  await page.goto("/");

  const input = page.getByRole("textbox");
  await input.fill("first");
  await input.press("Enter");
  await expect(page.locator("li")).toHaveCount(2);

  await input.fill("second");
  await input.press("Enter");
  await expect(page.locator("li")).toHaveCount(4);

  expect(backend.started).toHaveLength(2);
  expect(JSON.parse(backend.started[1])).toHaveLength(3);
});

/**
 * INVARIANT: All DOM updates must flow through the Binder (bindText, bindClass,
 * bindVisible, bindStyle, bindDisabled, bindAttr, bindContainerAttr,
 * bindChecked, bindSlot, bindList) or through child views composed via
 * show / showKeyed.
 *
 * Do NOT:
 *   - write a renderX(state) helper that sets innerHTML / appendChild /
 *     document.createElement and call it from sync();
 *   - mutate properties (.textContent, .className, .checked, .disabled, .src,
 *     href, style) directly inside a sync-time render function;
 *   - rebuild a list of children imperatively on every sync.
 *
 * Imperative renders bypass the binder, skip updates dispatched from the
 * internal loop, and destroy input focus / scroll / selection state every
 * time sync runs.
 *
 * If the binding primitive you need is missing, ADD A NEW bindX METHOD HERE
 * rather than working around it imperatively.
 *
 * Agent: before writing imperative DOM code in a view, stop and ask the user
 * for explicit confirmation.
 */

// A request is in exactly one of these states; the results/error live inside
// the variant that owns them, so "loaded but no results object" or "error with
// a null message" are not representable. `loading` keeps the previously loaded
// value (`prev`) so a view doesn't flash empty while the next value is fetched.
export type RequestStatus<T> =
  | { status: "idle" }
  | { status: "loading"; prev: T | null }
  | { status: "loaded"; data: T }
  | { status: "error"; error: string };

/** Views should implement this interface to be compatible with Bind. */
export interface View<State, _Message = never, _Ctx = unknown> {
  container: HTMLElement;
  sync(state: State): void;
  destroy(): void;
}

/** Constructor signature for Views. */
type ViewCtor<State, Message = never, Ctx = unknown> = new (
  container: HTMLElement,
  dispatch: (msg: Message) => void,
  initialState: State,
  ctx: Ctx,
) => View<State, Message, Ctx>;

/** Opaque descriptor returned by show(). Pass to bindSlot; do not inspect. */
export type SlotContent = {
  readonly __brand: "SlotContent";
};

/** Opaque descriptor returned by showKeyed(). Pass to bindList; do not inspect. */
export type KeyedSlotContent = {
  readonly __brand: "KeyedSlotContent";
};

interface SlotContentInternal {
  key?: string;
  ctor: ViewCtor<unknown, unknown, unknown>;
  state: unknown;
  ctx: unknown;
  childDispatch: (childMsg: unknown) => void;
}

interface KeyedSlotContentInternal {
  key: string;
  ctor: ViewCtor<unknown, unknown, unknown>;
  state: unknown;
  ctx: unknown;
  childDispatch: (childMsg: unknown) => void;
}

export const noop = () => {};

/**
 * Describes which view to show with which state, without actually mounting anything.
 * The slot reads this descriptor and handles the lifecycle: mount if new, sync if
 * the same view is already shown, or destroy-and-remount if the constructor changed.
 * childDispatch is the dispatch function passed to the child view. Use noop for leaf views.
 * An optional key forces a remount when it changes, even if the view class is the same.
 */
export function show<ChildState, ChildMsg, ChildCtx>(
  ViewClass: ViewCtor<ChildState, ChildMsg, ChildCtx>,
  state: ChildState,
  ctx: ChildCtx,
  childDispatch: (childMsg: ChildMsg) => void,
  key?: string,
): SlotContent {
  return {
    key,
    ctor: ViewClass,
    state,
    ctx,
    childDispatch,
  } as unknown as SlotContent;
}

/**
 * Like show, but uses a key to distinguish identity instead of the ViewClass.
 */
export function showKeyed<ChildState, ChildMsg, ChildCtx>(
  key: string,
  ViewClass: ViewCtor<ChildState, ChildMsg, ChildCtx>,
  state: ChildState,
  ctx: ChildCtx,
  childDispatch: (childMsg: ChildMsg) => void,
): KeyedSlotContent {
  return {
    key,
    ctor: ViewClass,
    state,
    ctx,
    childDispatch,
  } as unknown as KeyedSlotContent;
}

type Binding<State> = (state: State) => void;

/**
 * Manages bindings between state and DOM. Created in a view's constructor after setting innerHTML.
 * On each sync(), all registered bindings re-run with the new state.
 * On cleanup(), all child views are destroyed and bindings are cleared.
 */
export class Binder<State> {
  private bindings: Binding<State>[] = [];
  private container: HTMLElement;
  private cleanups: (() => void)[] = [];

  private state: State;

  constructor(container: HTMLElement, initialState: State) {
    this.container = container;
    this.state = initialState;
  }

  /** Query a single element by its data-ref attribute. Throws if not exactly one match. */
  ref<T extends HTMLElement = HTMLElement>(name: Ref): T {
    const els = this.container.querySelectorAll<T>(`[data-ref="${name}"]`);
    if (els.length !== 1) {
      throw new Error(`ref("${name}"): expected 1 match, found ${els.length}`);
    }
    return els[0];
  }

  sync(state: State): void {
    this.state = state;
    for (const b of this.bindings) b(state);
  }

  cleanup(): void {
    for (const c of this.cleanups) c();
    this.cleanups = [];
    this.bindings = [];
  }

  /** Bind the text of the element via textContent (for XSS protection) */
  bindText(ref: Ref, fn: (s: State) => string): void {
    const el = this.ref(ref);
    const binding = (s: State) => {
      el.textContent = fn(s);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  bindClass(refOrEl: Ref | HTMLElement, fn: (s: State) => string): void {
    const el = refOrEl instanceof HTMLElement ? refOrEl : this.ref(refOrEl);
    const binding = (s: State) => {
      el.className = fn(s);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  /** show or hide the element via display=none */
  bindVisible(ref: Ref, fn: (s: State) => boolean): void {
    const el = this.ref(ref);
    const binding = (s: State) => {
      el.style.display = fn(s) ? "" : "none";
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  /** Set inline styles on the element via a record. Clears properties removed between syncs. Values containing url( are stripped for safety. */
  bindStyle(ref: Ref, fn: (s: State) => Record<string, string>): void {
    const el = this.ref(ref);
    let prevKeys = new Set<string>();
    const binding = (s: State) => {
      const styles = fn(s);
      const nextKeys = new Set<string>();
      for (const [prop, val] of Object.entries(styles)) {
        el.style.setProperty(prop, val.replace(/url\s*\(/gi, ""));
        nextKeys.add(prop);
      }
      for (const prop of prevKeys) {
        if (!nextKeys.has(prop)) el.style.removeProperty(prop);
      }
      prevKeys = nextKeys;
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  /** Set the value of an input/textarea/select. Use for inputs whose value is driven by state (e.g. programmatic resets after submit, or syncing a select to the row's current role). */
  bindValue(ref: Ref, fn: (s: State) => string): void {
    const el = this.ref<
      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
    >(ref);
    const binding = (s: State) => {
      const v = fn(s);
      // Never clobber an input the user is actively editing — an unrelated
      // re-sync (e.g. an async dispatch elsewhere) would otherwise wipe out
      // an in-progress edit and blow away the caret.
      if (document.activeElement === el) return;
      if (el.value !== v) el.value = v;
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  bindChecked(ref: Ref, fn: (s: State) => boolean): void {
    const el = this.ref<HTMLInputElement>(ref);
    const binding = (s: State) => {
      el.checked = fn(s);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  bindDisabled(ref: Ref, fn: (s: State) => boolean): void {
    const el = this.ref<
      HTMLButtonElement | HTMLInputElement | HTMLSelectElement
    >(ref);
    const binding = (s: State) => {
      el.disabled = fn(s);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  bindAttr(ref: Ref, attr: string, fn: (s: State) => string | undefined): void {
    const el = this.ref(ref);
    const binding = (s: State) => {
      const val = fn(s);
      if (val === undefined) el.removeAttribute(attr);
      else el.setAttribute(attr, val);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  /** Bind an attribute on the root container element (the element passed to the view's constructor). */
  bindContainerAttr(attr: string, fn: (s: State) => string | undefined): void {
    const el = this.container;
    const binding = (s: State) => {
      const val = fn(s);
      if (val === undefined) el.removeAttribute(attr);
      else el.setAttribute(attr, val);
    };
    this.bindings.push(binding);
    binding(this.state);
  }

  /** Conditionally mount/unmount a child view. Return show() to mount, undefined to unmount. */
  bindSlot(ref: Ref, fn: (s: State) => SlotContent | undefined): void {
    const el = this.ref(ref);
    let currentCtor: SlotContentInternal["ctor"] | undefined;
    let currentKey: string | undefined;
    let currentView: View<unknown, unknown> | undefined;

    const cleanup = () => {
      if (currentView) {
        currentView.destroy();
        el.innerHTML = "";
        currentView = undefined;
        currentCtor = undefined;
        currentKey = undefined;
      }
    };

    const binding = (s: State) => {
      const result = fn(s);
      const content = result as unknown as SlotContentInternal | undefined;
      if (!content) {
        cleanup();
      } else if (content.ctor !== currentCtor || content.key !== currentKey) {
        cleanup();
        currentView = new content.ctor(
          el,
          content.childDispatch,
          content.state,
          content.ctx,
        );
        currentCtor = content.ctor;
        currentKey = content.key;
      } else {
        currentView?.sync(content.state as State);
      }
    };
    this.bindings.push(binding);
    binding(this.state);

    this.cleanups.push(cleanup);
  }

  /** Keyed list reconciliation. Maps an array of showKeyed() descriptors to child views. */
  bindList(
    ref: Ref,
    childTag: string,
    fn: (s: State) => KeyedSlotContent[],
  ): void {
    const el = this.ref(ref);
    const children = new Map<
      string,
      {
        view: View<unknown>;
        ctor: ViewCtor<unknown, unknown, unknown>;
        el: HTMLElement;
      }
    >();

    const cleanup = () => {
      for (const [, child] of children) child.view.destroy();
      children.clear();
      el.innerHTML = "";
    };

    const binding = (s: State) => {
      const items = fn(s) as unknown as KeyedSlotContentInternal[];
      const nextKeys = new Set<string>();

      for (const item of items) {
        nextKeys.add(item.key);
        let child = children.get(item.key);

        if (child && child.ctor !== item.ctor) {
          child.view.destroy();
          child.el.innerHTML = "";
          const newView = new item.ctor(
            child.el,
            item.childDispatch,
            item.state,
            item.ctx,
          );
          child.view = newView;
          child.ctor = item.ctor;
        } else if (!child) {
          const childEl = document.createElement(childTag);
          const view = new item.ctor(
            childEl,
            item.childDispatch,
            item.state,
            item.ctx,
          );
          child = { view, ctor: item.ctor, el: childEl };
          children.set(item.key, child);
        }

        child.view.sync(item.state);
      }

      for (const [key, child] of children) {
        if (!nextKeys.has(key)) {
          child.el.remove();
          child.view.destroy();
          children.delete(key);
        }
      }

      // Reorder with the minimum number of DOM moves. An element can stay put
      // iff it participates in the longest common subsequence of current-order
      // vs target-order (distinct keys ⇒ LIS of current DOM indices read in
      // target order). Everything else — including freshly-created children,
      // which have no current position — must be inserted.
      //
      // Avoiding spurious appendChild calls matters because moving an element
      // (or an ancestor of a focused input) blurs focus on the input.
      const elToDomIndex = new Map<HTMLElement, number>();
      for (let i = 0; i < el.children.length; i++) {
        elToDomIndex.set(el.children[i] as HTMLElement, i);
      }
      const targetDomIndex: number[] = items.map((item) => {
        const child = children.get(item.key);
        return child ? (elToDomIndex.get(child.el) ?? -1) : -1;
      });
      const inLis = computeLisMask(targetDomIndex);

      let anchor: Node | null = null;
      for (let i = items.length - 1; i >= 0; i--) {
        const child = children.get(items[i].key);
        if (!child) continue;
        if (inLis[i]) {
          anchor = child.el;
        } else {
          el.insertBefore(child.el, anchor);
          anchor = child.el;
        }
      }
    };
    this.bindings.push(binding);
    binding(this.state);

    this.cleanups.push(cleanup);
  }
}

/**
 * Given an array of indices, return a boolean mask marking entries that
 * participate in one longest increasing subsequence. Entries with value < 0
 * are treated as sentinels for "not currently in DOM" and are never marked.
 * O(n log n) via patience sorting with predecessor links.
 */
function computeLisMask(arr: number[]): boolean[] {
  const n = arr.length;
  const mask = new Array<boolean>(n).fill(false);
  if (n === 0) return mask;

  // tails[k] = index into arr of the smallest tail of an increasing
  // subsequence of length k+1 seen so far.
  const tails: number[] = [];
  const prev: (number | null)[] = new Array(n).fill(null);

  for (let i = 0; i < n; i++) {
    const v = arr[i];
    if (v < 0) continue;
    let lo = 0;
    let hi = tails.length;
    while (lo < hi) {
      const mid = (lo + hi) >>> 1;
      if (arr[tails[mid]] < v) lo = mid + 1;
      else hi = mid;
    }
    if (lo > 0) prev[i] = tails[lo - 1];
    tails[lo] = i;
  }

  let k: number | null = tails.length > 0 ? tails[tails.length - 1] : null;
  while (k !== null) {
    mask[k] = true;
    k = prev[k];
  }
  return mask;
}

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/**
 * Wrapper marking a string as already-safe, hand-authored HTML that must be
 * injected verbatim (not escaped) by `sanitize`. ONLY ever construct this from
 * static, trusted constants (e.g. the inline-SVG icons in `icons.ts`) — never
 * from user data, or you reintroduce an XSS hole.
 */
export class RawHtml {
  readonly html: string;
  constructor(html: string) {
    this.html = html;
  }
}

/** Mark a trusted, static HTML string for raw (unescaped) injection. */
export function raw(html: string): RawHtml {
  return new RawHtml(html);
}

/**
 * Tagged template that HTML-escapes all interpolated values. Use for all
 * innerHTML assignments. Values wrapped in `RawHtml` (via `raw()`) pass through
 * unescaped — reserved for trusted static markup such as inline-SVG icons.
 */
export function sanitize(
  strings: TemplateStringsArray,
  ...values: unknown[]
): string {
  return strings.reduce(
    (out, str, i) =>
      out +
      str +
      (i < values.length
        ? values[i] instanceof RawHtml
          ? (values[i] as RawHtml).html
          : escapeHtml(String(values[i]))
        : ""),
    "",
  );
}

/**
 * A typed post-render event bus.
 *
 * Bridges the reducer phase and the DOM phase of a dispatch loop. Reducers
 * (which must never touch the DOM) `emit` events while handling a message; the
 * root loop calls `flush` after the view has synced, delivering each queued
 * event to every currently-subscribed view. Subscribed views do the imperative
 * DOM work (scroll, focus, measure) scoped to their own container/refs.
 *
 * Generic over an app-supplied event union.
 */
export class PostRenderEventBus<Event> {
  private queue: Event[] = [];
  private subscribers = new Set<(event: Event) => void>();

  /** Queue an event during a dispatch. Called from the reducer side. */
  emit(event: Event): void {
    this.queue.push(event);
  }

  /** Register a listener. Returns an unsubscribe function for use in destroy(). */
  subscribe(handler: (event: Event) => void): () => void {
    this.subscribers.add(handler);
    return () => {
      this.subscribers.delete(handler);
    };
  }

  /**
   * Deliver all queued events to the current subscribers, then clear the queue.
   * Called by the root loop after the view is synced.
   */
  flush(): void {
    if (this.queue.length === 0) return;
    const events = this.queue;
    this.queue = [];
    for (const event of events) {
      for (const handler of this.subscribers) {
        handler(event);
      }
    }
  }
}

/** Branded string type for data-ref names. Prevents accidental use of raw strings in binder methods. */
export type Ref = string & { readonly __brand: "Ref" };

let refCounter = 0;

/** Generate a unique data-ref name. Use in templates and binder methods to avoid cross-view collisions. */
export function ref(prefix: string): Ref {
  return `${prefix}_${refCounter++}` as Ref;
}

let clsCounter = 0;

/** Generate a unique CSS class name. Avoids style collisions between components. */
export function cls(prefix: string): string {
  return `${prefix}_${clsCounter++}`;
}

/**
 * Smoothly scroll an element into view. This is a layout side effect (no DOM
 * creation), so it is the one sanctioned imperative touch — drive it from a
 * post-render subscriber via a `ref`, never from a `sync`-time render.
 */
export function scrollIntoView(el: HTMLElement): void {
  el.scrollIntoView({ behavior: "smooth", block: "start" });
}

/** Inject a raw CSS string into the page via a <style> tag. */
export function mountStyle(css: string): void {
  const el = document.createElement("style");
  el.textContent = css;
  document.head.appendChild(el);
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

export type Message = { role: "user" | "assistant"; text: string };

/** The subset of WebSocket the conversation uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export class Conversation {
  private readonly turns: Anthropic.MessageParam[];
  private pending: { requestId: string; blocks: string[] } | undefined;
  private settle: (() => void) | undefined;
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | undefined;

  constructor(
    socket: Socket,
    opts: {
      system?: string;
      initialTurns?: Anthropic.MessageParam[];
      seed?: string;
    } = {},
  ) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.seed = opts.seed;
    this.turns = opts.seed
      ? [{ role: "user", content: opts.seed }]
      : [...(opts.initialTurns ?? [])];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** Committed turns plus the one currently streaming. */
  get messages(): ReadonlyArray<Message> {
    const turns = this.seed ? this.turns.slice(1) : this.turns;
    const committed = turns.map(
      (turn): Message => ({
        role: turn.role === "assistant" ? "assistant" : "user",
        text: textOf(turn),
      }),
    );
    const streaming = this.pending?.blocks.join("");
    if (streaming) committed.push({ role: "assistant", text: streaming });
    return committed;
  }

  get inFlight(): boolean {
    return this.pending !== undefined;
  }

  send(text: string): Promise<void> {
    if (this.pending) return Promise.resolve();
    this.turns.push({ role: "user", content: text });
    return this.request();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<void> {
    if (this.pending || this.turns.length === 0) return Promise.resolve();
    return this.request();
  }

  private request(): Promise<void> {
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [] };
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<void>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start":
        pending.blocks[event.index] = blockStartText(event.content_block);
        break;
      case "content_block_delta":
        pending.blocks[event.index] =
          (pending.blocks[event.index] ?? "") + deltaText(event.delta);
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
      case "message_delta":
      case "content_block_stop":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    const text = pending.blocks.join("");
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (text.length > 0) this.turns.push({ role: "assistant", content: text });
    this.settle?.();
    this.settle = undefined;
  }
}

function textOf(turn: Anthropic.MessageParam): string {
  if (typeof turn.content === "string") return turn.content;
  return turn.content
    .map((block) => (block.type === "text" ? block.text : ""))
    .join("");
}

/** This prototype has no tools and no thinking, so the non-text variants are
 * listed to be explicitly ignored rather than silently dropped - when we add
 * them, this is where they surface. */
function blockStartText(block: Anthropic.ContentBlock): string {
  switch (block.type) {
    case "text":
      return block.text;
    default:
      console.warn("unhandled content block", block);
      return "";
  }
}

function deltaText(delta: Anthropic.RawContentBlockDelta): string {
  switch (delta.type) {
    case "text_delta":
      return delta.text;
    default:
      console.warn("unhandled content block delta", delta);
      return "";
  }
}

